Widget _menuSvg(String raw, Color color, double size) {
  return SvgPicture.string(
    raw,
    width: size,
    height: size,
    colorFilter: ColorFilter.mode(color, BlendMode.srcIn),
  );
}

Widget iconRanapSvg(Color color, {double size = 26}) => _menuSvg(_svgRanap, color, size);
Widget iconPoliSvg(Color color, {double size = 26}) => _menuSvg(_svgPoli, color, size);
Widget iconIgdSvg(Color color, {double size = 26}) => _menuSvg(_svgIgd, color, size);
Widget iconCutiSvg(Color color, {double size = 26}) => _menuSvg(_svgCuti, color, size);
